def load_nhl_groups(return_as_pandas: bool = False):
    """Load nhl_groups (sportsdataverse-data release).

    Source: https://github.com/sportsdataverse/sportsdataverse-data/releases/tag/nhl_groups

    Args:
        return_as_pandas: return a pandas DataFrame instead of polars.

    Returns:
        A polars (or pandas) DataFrame; an absent asset yields an empty frame
        with a warning rather than raising (404-safe).

        |col_name     |type   |
        |:------------|:------|
        |league       |String |
        |group_id     |String |
        |level        |String |
        |first_season |Int32  |
        |last_season  |Int32  |
        |notes        |String |

    Note:
        One season-less file: one row per group lineage (the league, subdivisions, conferences, divisions) with the first and last season it had members. group_id is SDV's own id (e.g. nhl:metropolitan) and names a lineage: a rename that keeps continuity keeps the id, a new body gets a new one, and notes records each call. Seasons are the ENDING year (2025 = the 2024-25 season).

    Example:
        Quick start::

            load_nhl_groups()
    """
    # One asset for the whole dataset (no {season} token in the manifest url), so
    # there is no season loop: an absent asset is an empty frame plus a warning,
    # the same 404-safe contract the per-season loaders keep per season.
    df = _read_release_parquet(
        "https://github.com/sportsdataverse/sportsdataverse-data/releases/download/nhl_groups/nhl_groups.parquet"
    )
    if df is None:
        cli_warn("load_nhl_groups: no published asset (returning an empty frame)")
    out = df if df is not None else pl.DataFrame()
    return out.to_pandas(use_pyarrow_extension_array=True) if return_as_pandas else out


